/**
 * 现场拍照防伪水印工具
 * 需求：禅道任务 2920 / story 1552 —— 业主上报照片叠加「当前时间 + 定位详细地址」水印。
 * - 定位失败时地址显示「定位失败」，但时间水印必须生成。
 * - H5：canvasToTempFilePath 返回 base64，转 File 供 uni.uploadFile 的 files 通道上传。
 * - 小程序/App：返回临时文件路径，走 uni.uploadFile 的 filePath 通道。
 */
import { QQ_MAP_KEY } from '@/utils/file'

const REVERSE_GEOCODE_TIMEOUT = 3000

/** 逆地理编码：坐标 -> 详细地址；失败/超时返回空串 */
function reverseGeocode(latitude, longitude) {
  // #ifdef H5
  const base = 'map'
  // #endif
  // #ifndef H5
  const base = 'https://apis.map.qq.com'
  // #endif

  return new Promise((resolve) => {
    let settled = false
    const finish = (addr) => {
      if (settled) return
      settled = true
      resolve(addr || '')
    }
    const timer = setTimeout(() => finish(''), REVERSE_GEOCODE_TIMEOUT)
    uni.request({
      url: `${base}/ws/geocoder/v1`,
      data: {
        location: `${latitude},${longitude}`,
        key: QQ_MAP_KEY,
      },
      method: 'GET',
      dataType: 'json',
      success: (res) => {
        clearTimeout(timer)
        const addr = res && res.data && res.data.result && res.data.result.address
        finish(addr || '')
      },
      fail: () => {
        clearTimeout(timer)
        finish('')
      },
    })
  })
}

/** 获取定位地址；未授权/失败一律返回「定位失败」，不阻断拍照 */
function resolveLocationAddress() {
  return new Promise((resolve) => {
    uni.getLocation({
      type: 'gcj02',
      success: async (res) => {
        const addr = await reverseGeocode(res.latitude, res.longitude)
        resolve(addr || '定位失败')
      },
      fail: () => resolve('定位失败'),
    })
  })
}

function pad(n) {
  return n < 10 ? `0${n}` : `${n}`
}

/** 当前时间 yyyy-MM-dd HH:mm:ss */
function formatNow(date = new Date()) {
  return (
    `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ` +
    `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`
  )
}

/** 固定画布尺寸（与 ZsUploader 内隐藏 canvas 节点一致） */
export const WATERMARK_CANVAS_W = 750
export const WATERMARK_CANVAS_H = 1334

/** 取图片真实尺寸 */
function getImageInfo(src) {
  return new Promise((resolve, reject) => {
    uni.getImageInfo({ src, success: resolve, fail: reject })
  })
}

/**
 * H5 base64 -> File（供 uni.uploadFile files 通道）
 */
function base64ToFile(base64, filename = 'watermark.jpg') {
  const parts = String(base64).split(',')
  const mimeMatch = parts[0] && parts[0].match(/:(.*?);/)
  const mime = mimeMatch ? mimeMatch[1] : 'image/jpeg'
  const b64 = parts.length > 1 ? parts[1] : parts[0]
  const binary = atob(b64)
  const bytes = new Uint8Array(binary.length)
