function base64ToFile(base64, filename = 'watermark.jpg') {
  const parts = String(base64).split(',')
  const mimeMatch = parts[0] && parts[0].match(/:(.*?);/)
  const mime = mimeMatch ? mimeMatch[1] : 'image/jpeg'
  const b64 = parts.length > 1 ? parts[1] : parts[0]
  const binary = atob(b64)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i)
  const blob = new Blob([bytes], { type: mime })
  return new File([blob], filename, { type: mime })
}

/**
 * 在临时图片上绘制水印并导出可上传的结果。
 * @param {String} filePath 拍照得到的临时文件路径
 * @param {Object} ctx canvas 上下文（由调用方用 uni.createCanvasContext 创建，绑定页面内 canvas 节点）
 * @param {String} canvasId canvas-id
 * @param {Object} component 组件实例（小程序端 canvasToTempFilePath 需要）
 * @returns {Promise<{filePath?:string, file?:File}>} 可直接传给 fileUpload 的对象
 */
export async function applyWatermark(filePath, { ctx, canvasId, component }) {
  const width = WATERMARK_CANVAS_W
  const height = WATERMARK_CANVAS_H
  const address = await resolveLocationAddress()

  ctx.clearRect(0, 0, width, height)
  // 图片等比缩放居中，避免拉伸变形；留白填黑
  ctx.fillStyle = '#000000'
  ctx.fillRect(0, 0, width, height)
  const info = await getImageInfo(filePath).catch(() => ({ width: 0, height: 0 }))
  let imageBottom = height
  if (info.width && info.height) {
    const scale = Math.min(width / info.width, height / info.height)
    const dw = info.width * scale
    const dh = info.height * scale
    const dx = (width - dw) / 2
    const dy = (height - dh) / 2
    imageBottom = dy + dh
    ctx.drawImage(filePath, dx, dy, dw, dh)
  } else {
    ctx.drawImage(filePath, 0, 0, width, height)
  }

  // 水印：灰字直接覆盖在图片底部画面上，轻阴影保证浅色照片上也醒目
  const lines = [`时间：${formatNow()}`, `位置：${address || '定位失败'}`]
  const fontSize = 30
  const lineHeight = fontSize * 1.45
  const padding = fontSize
  const bottomInset = fontSize * 0.6
  // 缩略图为正方形 object-fit:cover，仅显示画布中央正方形区；画布固定 750×1334 时
  // 该区下沿 = (height + width) / 2。水印基线锚在此下沿，确保正方形缩略图也能看到水印。
  // 宽图/非标准尺寸取 imageBottom 与该下沿的较小值，避免落到可见区外。
  const coverVisibleBottom = Math.min(imageBottom, (height + width) / 2)

  if (typeof ctx.setShadow === 'function') {
    ctx.setShadow(0, 1, 2, 'rgba(0,0,0,0.75)')
  }
  ctx.fillStyle = '#b0b0b0'
  ctx.font = `bold ${fontSize}px sans-serif`
  ctx.textAlign = 'left'
  ctx.textBaseline = 'bottom'
  lines.forEach((line, i) => {
    ctx.fillText(line, padding, coverVisibleBottom - bottomInset - (lines.length - 1 - i) * lineHeight)
  })
  if (typeof ctx.setShadow === 'function') {
    ctx.setShadow(0, 0, 0, 'transparent')
  }
  ctx.draw(false)

  return new Promise((resolve, reject) => {
    uni.canvasToTempFilePath(
      {
        canvasId,
        x: 0,
        y: 0,
        width,
        height,
        destWidth: width,
        destHeight: height,
        fileType: 'jpg',
        quality: 0.9,
        success: (res) => {
          const out = res.tempFilePath
          // #ifdef H5
          resolve({ file: base64ToFile(out) })
          // #endif
          // #ifndef H5
          resolve({ filePath: out })
          // #endif
        },
        fail: reject,
      },
      component
    )
  })
}

